List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    result.add(new ArrayList<>());
    for (int x : nums) {
        int size = result.size();
        for (int i = 0; i < size; i++) {      // every subset so far, now with x too
