function subsets(nums) {
  const result = [];
  const path = [];
  const decide = (i) => {
    if (i === nums.length) {                 // every number decided: one subset
      result.push([...path]);
      return;
    }
    path.push(nums[i]);                      // take nums[i]
    decide(i + 1);
    path.pop();                              // un-take it ...
    decide(i + 1);                           // ... and skip it
  };
  decide(0);
  return result;
}

List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    decide(nums, 0, new ArrayList<>(), result);
    return result;
}

void decide(int[] nums, int i, List<Integer> path, List<List<Integer>> result) {
    if (i == nums.length) {                  // every number decided: one subset
        result.add(new ArrayList<>(path));
        return;
    }
    path.add(nums[i]);                       // take nums[i]
    decide(nums, i + 1, path, result);
    path.remove(path.size() - 1);            // un-take it ...
    decide(nums, i + 1, path, result);       // ... and skip it
}

void decide(vector<int>& nums, int i, vector<int>& path, vector<vector<int>>& result) {
    if (i == (int)nums.size()) {             // every number decided: one subset
        result.push_back(path);
        return;
    }
    path.push_back(nums[i]);                 // take nums[i]
    decide(nums, i + 1, path, result);
    path.pop_back();                         // un-take it ...
    decide(nums, i + 1, path, result);       // ... and skip it
}

